import {defaults,formatTime,ranking,validTime,readState} from './model.js';
// shortcut: friends and history are demo data; replace with verified device data and a backend for real competitions.
let state;try{state=readState(localStorage.getItem('offscreen-demo'));}catch{state={...defaults,joined:[]};}
let current='overview',period='week',rankPeriod='today',toastTimer;
const content=document.querySelector('#content');
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',3500);}
function save(){try{localStorage.setItem('offscreen-demo',JSON.stringify(state));return true;}catch{toast('Saved for this visit. Browser storage is unavailable.');return false;}}
function rows(){return ranking(state.minutes).map((f,i)=>`<div class="rank-row ${f.self?'self':''}"><span class="rank-num">${i+1}</span><span class="avatar" style="background:${f.color}">${f.initials}</span><div class="rank-name">${f.self?'You':f.name}<small>${f.self?'Keep making room for life':f.note}</small></div><span class="rank-time">${formatTime(f.minutes)}</span></div>`).join('');}
function chart(){const values=period==='week'?[185,152,178,130,140,119,state.minutes]:[215,187,161,142];const names=period==='week'?['Tue','Wed','Thu','Fri','Sat','Sun','Mon']:['Wk 1','Wk 2','Wk 3','Wk 4'];const max=Math.max(240,...values);return `<div class="chart" role="img" aria-label="${values.map((v,i)=>`${names[i]}: ${formatTime(v)}`).join(', ')}"><div class="axis"><span>${Math.ceil(max/60)}h</span><span>${Math.round(max/120)}h</span><span>0h</span></div>${values.map((v,i)=>`<div class="bar-wrap"><div class="bar ${i===values.length-1?'today':''}" style="height:${v/max*100}%" title="${names[i]}: ${formatTime(v)}"></div><small>${names[i]}</small></div>`).join('')}</div>`;}
function overview(){const improvement=185-state.minutes;const saved=Math.max(0,240-state.minutes);return `<div class="grid"><section class="card"><div class="card-top"><span class="label">Today's screen time</span><span class="tag">${state.minutes<=state.goal?'Within your goal':'A fresh start tomorrow'}</span></div><div class="metric">${Math.floor(state.minutes/60)}<span>h</span> ${String(state.minutes%60).padStart(2,'0')}<span>m</span></div><div class="delta">${improvement>=0?'↘':'↗'} ${formatTime(Math.abs(improvement))} ${improvement>=0?'less':'more'} than last Monday</div><div class="stats-foot"><span>Your daily goal <strong>${formatTime(state.goal)}</strong></span><span>${state.minutes<=state.goal?formatTime(state.goal-state.minutes)+' to spare':formatTime(state.minutes-state.goal)+' over goal'}</span></div></section><section class="card summary"><span class="label">OFFLINE IS A GOOD PLACE TO BE.</span><h2>${formatTime(saved)}<br>back to you.</h2><p>Time reclaimed today compared with your 4-hour demo baseline.</p><div class="sun-art" aria-hidden="true"></div></section><section class="card weekly"><div class="card-top"><span class="label">A little better, every day</span><div class="segmented"><button data-period="week" class="${period==='week'?'selected':''}">Week</button><button data-period="month" class="${period==='month'?'selected':''}">Month</button></div></div>${chart()}<div class="chart-note"><span><i class="dot"></i>Daily screen time</span><span>${period==='week'?'Oct 20 – 26':'October · weekly averages'}</span></div></section><section class="card leaderboard"><div class="card-top"><span class="label">Your circle, less scrolling</span><button class="text-button" data-view="friends">View all ↗</button></div><p>Today's leaderboard · Lowest time wins</p>${rows().split('</div></div>').join('</div></div>')}<div class="leader-footer">Good company. A little healthy competition.</div></section><section class="card challenge-mini"><div class="challenge-icon">⚑</div><div><h3>The under-2-hour club</h3><p>A small goal. A whole week of more life.</p></div><button class="text-button" data-view="challenges">Explore ↗</button></section></div><div class="section-title"><h2>Good things happening</h2><span class="muted">From your circle</span></div><section class="card activity"><div class="avatar" style="background:#e1e7d7">SC</div><div class="activity-content"><strong>Sophie made time for something better.</strong><div class="activity-meta">Today, 9:42 AM · Demo activity</div><p>“Finished the book that's been on my bedside table for three months. Turns out I did have the time.”</p><button class="kudos" id="kudos" aria-pressed="${state.kudos}">${state.kudos?'♥':'♡'} ${state.kudos?'You and 8 others':'Send kudos · 8'}</button></div><span class="tag">Under 2 hours</span></section>`;}
function challenges(){return `<div class="challenge-grid">${[{id:'two-hour',title:'The under-2-hour club',description:'Keep your daily screen time below 2 hours. Seven days to make more room for real life.',people:'18 people taking it one day at a time',time:'OCT 26 – NOV 1',progress:state.minutes<120?14:0},{id:'weekend',title:'A weekend, unplugged.',description:'Spend less than 90 minutes a day on your phone this weekend. Leave space for a little adventure.',people:'12 people choosing to switch off',time:'OCT 31 – NOV 1',progress:0}].map(c=>`<section class="card challenge-card"><div class="card-top"><div class="challenge-icon">⚑</div><span class="tag">${c.time}</span></div><h2>${c.title}</h2><p>${c.description}</p><div class="muted">${c.people}</div><div class="progress"><span style="width:${state.joined.includes(c.id)?c.progress:0}%"></span></div><div class="muted">${state.joined.includes(c.id)?c.id==='two-hour'?(c.progress?'1 of 7 days under goal':'0 of 7 days under goal'):'Starts Saturday':'Join to track your progress'}</div><button class="primary" data-join="${c.id}">${state.joined.includes(c.id)?'Joined · Leave challenge':'Join challenge ↗'}</button></section>`).join('')}</div><p class="muted">Prototype challenges use demo participants. Joining is saved only on this device.</p>`;}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===current));const titles={overview:'A little less screen.<br>A lot more life.',friends:'Better together.<br>Less screen, more team.',challenges:'Small challenges.<br>Real-life rewards.',profile:'Make time.<br>For your kind of life.'};const subtitles={overview:"Make room for the good stuff. You're doing great.",friends:'Your circle keeps you going. Lowest daily screen time wins.',challenges:'A friendly nudge to put your phone down.',profile:'A little intention goes a long way.'};document.querySelector('#page-title').innerHTML=titles[current];document.querySelector('#page-subtitle').textContent=subtitles[current];if(current==='overview')content.innerHTML=overview();if(current==='friends')content.innerHTML=`<section class="card full-leader"><div class="card-top"><h2>Your circle</h2><span class="tag">TODAY · DEMO FRIENDS</span></div>${rows()}<p class="muted">Ranked by total screen time, lowest first. Your manual check-in updates your position immediately.</p></section>`;if(current==='challenges')content.innerHTML=challenges();if(current==='profile')content.innerHTML=`<section class="card profile-card"><div class="avatar you">JD</div><h2>Jamie Davis</h2><p>Finding my balance. One day at a time.</p><form id="goal-form"><label for="goal">Your daily screen-time goal, in minutes</label><input id="goal" type="number" min="15" max="1440" step="1" value="${state.goal}" required><button class="primary">Save goal</button></form><p class="muted">Current goal: ${formatTime(state.goal)} per day.</p><hr style="border:0;border-top:1px solid #e7ebe5;margin:25px 0"><strong>Your data stays here.</strong><p class="muted">This prototype saves your check-in, goal, kudos, and challenge choices in this browser. Friends and historical results are fictional. No account or automatic device tracking is connected.</p></section>`;}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){current=nav.dataset.view;render();window.scrollTo({top:0});}const periodButton=e.target.closest('[data-period]');if(periodButton){period=periodButton.dataset.period;render();}const join=e.target.closest('[data-join]');if(join){const id=join.dataset.join;state.joined=state.joined.includes(id)?state.joined.filter(x=>x!==id):[...state.joined,id];const persisted=save();render();if(persisted)toast(state.joined.includes(id)?'You’re in. Make a little more room for life.':'You left this challenge.');}if(e.target.closest('#kudos')){state.kudos=!state.kudos;save();render();}});
const dialog=document.querySelector('#log-dialog');document.querySelector('#log-open').onclick=()=>{document.querySelector('#hours').value=Math.floor(state.minutes/60);document.querySelector('#minutes').value=state.minutes%60;document.querySelector('#log-error').textContent='';dialog.showModal();};document.querySelector('.close').onclick=()=>dialog.close();
document.querySelector('#log-form').onsubmit=e=>{e.preventDefault();const h=Number(document.querySelector('#hours').value),m=Number(document.querySelector('#minutes').value);if(!validTime(h,m)){document.querySelector('#log-error').textContent='Enter a time between 0 minutes and 24 hours.';return;}state.minutes=h*60+m;const persisted=save();dialog.close();render();if(persisted)toast('Check-in saved. Your ranking is updated.');};
document.addEventListener('submit',e=>{if(e.target.id==='goal-form'){e.preventDefault();const goal=Number(document.querySelector('#goal').value);if(!Number.isInteger(goal)||goal<15||goal>1440)return;state.goal=goal;const persisted=save();render();if(persisted)toast('Your daily goal is updated.');}});render();
